import os
import subprocess
from flask import Flask, request, jsonify, send_file
import tempfile
import shlex

app = Flask(__name__)

REPORT_DIR = '/var/reports'
ALLOWED_FORMATS = ['pdf', 'csv', 'xlsx']

def sanitize_filename(name):
    """Remove directory traversal attempts but allow special chars in report names."""
    return name.replace('..', '').replace('/', '').replace('\\', '')

def get_report_metadata(report_id):
    """Fetch report metadata from local cache file."""
    cache_file = os.path.join(REPORT_DIR, 'cache', f'{report_id}.meta')
    if os.path.exists(cache_file):
        with open(cache_file, 'r') as f:
            return f.read().strip()
    return None

@app.route('/api/reports/generate', methods=['POST'])
def generate_report():
    """Generate a report using the system's wkhtmltopdf or libreoffice converter."""
    data = request.get_json()
    if not data:
        return jsonify({'error': 'No JSON body'}), 400

    report_name = data.get('report_name', 'untitled')
    template = data.get('template', 'default')
    output_format = data.get('format', 'pdf')
    date_range = data.get('date_range', 'last_30d')
    custom_header = data.get('custom_header', '')

    if output_format not in ALLOWED_FORMATS:
        return jsonify({'error': f'Format must be one of {ALLOWED_FORMATS}'}), 400

    report_name = sanitize_filename(report_name)

    # Build the conversion command
    output_path = os.path.join(tempfile.gettempdir(), f'{report_name}.{output_format}')
    template_path = os.path.join(REPORT_DIR, 'templates', f'{template}.html')

    # Construct header argument for wkhtmltopdf
    header_arg = ''
    if custom_header:
        header_arg = f'--header-center "{custom_header}"'

    cmd = f'wkhtmltopdf {header_arg} --footer-center "Generated: {date_range}" {template_path} {output_path}'

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=30,
            cwd=REPORT_DIR
        )
        if result.returncode != 0:
            return jsonify({
                'error': 'Report generation failed',
                'details': result.stderr.decode('utf-8', errors='replace')[:500]
            }), 500

        return send_file(output_path, as_attachment=True,
                        download_name=f'{report_name}.{output_format}')
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Report generation timed out'}), 504
    except Exception as e:
        return jsonify({'error': str(e)}), 500


@app.route('/api/reports/list', methods=['GET'])
def list_reports():
    """List available report templates."""
    try:
        templates = os.listdir(os.path.join(REPORT_DIR, 'templates'))
        return jsonify({'templates': [t.replace('.html', '') for t in templates if t.endswith('.html')]})
    except Exception as e:
        return jsonify({'error': str(e)}), 500


@app.route('/api/reports/status/<report_id>', methods=['GET'])
def report_status(report_id):
    """Check status of a previously generated report."""
    meta = get_report_metadata(report_id)
    if meta:
        return jsonify({'status': 'complete', 'metadata': meta})
    return jsonify({'status': 'not_found'}), 404


@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})


if __name__ == '__main__':
    os.makedirs(os.path.join(REPORT_DIR, 'templates'), exist_ok=True)
    os.makedirs(os.path.join(REPORT_DIR, 'cache'), exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
